CREATE UNIQUE INDEX episode_progress_unique ON public.episode_progress USING btree (user_id, media_id, season, episode);

CREATE UNIQUE INDEX follows_follower_id_following_id_key ON public.follows USING btree (follower_id, following_id);

CREATE UNIQUE INDEX follows_pkey ON public.follows USING btree (id);

CREATE INDEX idx_episode_progress_user_media ON public.episode_progress USING btree (user_id, media_id);

