CREATE UNIQUE INDEX movies_pkey ON public.movies USING btree (id, title);

alter table "public"."episode_progress" add constraint "episode_progress_pkey" PRIMARY KEY using index "episode_progress_pkey";

alter table "public"."follows" add constraint "follows_pkey" PRIMARY KEY using index "follows_pkey";

