  create policy "Users can manage their own episode progress"
  on "public"."episode_progress"
  as permissive
  for all
  to public
using ((auth.uid() = user_id))
with check ((auth.uid() = user_id));



  create policy "follows_delete"
  on "public"."follows"
  as permissive
  for delete
  to authenticated
using ((auth.uid() = follower_id));



  create policy "follows_insert"
  on "public"."follows"
  as permissive
  for insert
  to authenticated
with check (((auth.uid() = follower_id) AND (auth.uid() <> following_id)));



  create policy "follows_select"
  on "public"."follows"
  as permissive
  for select
  to authenticated
using (((auth.uid() = follower_id) OR (auth.uid() = following_id)));



